var normalizeRef = null;

// Host calls this to inject the normalize function from normalize.js
function setNormalize(fn) {
  normalizeRef = (typeof fn === 'function') ? fn : null;
}

var TOKEN_RE = /[A-Za-z0-9]+(?:'[A-Za-z0-9]+)*/g;

function tokenize(text) {
  var norm;
  if (normalizeRef) {
    norm = normalizeRef(text);
  } else {
    // Fallback: basic normalization if injection is unavailable
    var t = (typeof text === 'string') ? text : '';
    norm = t.replace(/\s+/g, ' ').replace(/^ | $/g, '').toLowerCase();
  }
  if (typeof norm !== 'string' || norm.length === 0) {
    return [];
  }
  var out = [];
  var m;
  TOKEN_RE.lastIndex = 0;
  while ((m = TOKEN_RE.exec(norm)) !== null) {
    out.push(m[0]);
  }
  return out;
}
", "pipeline.js": "var _tokenize = null;

function injectTokenize(fn) {
  _tokenize = fn;
}

function processText(text) {
  var tokens = _tokenize(text);
  var count = tokens.length;
  var unique = [];
  var seen = Object.create(null);
  var frequencies = Object.create(null);
  for (var i = 0; i < count; i++) {
    var t = tokens[i];
    if (!Object.prototype.hasOwnProperty.call(seen, t)) {
      seen[t] = true;
      unique.push(t);
      frequencies[t] = 1;
    } else {
      frequencies[t]++;
    }
  }
  return {
    text: tokens.join(' '),
    tokens: tokens,
    count: count,
    unique: unique,
    frequencies: frequencies
  };
}
